
$(function () {
  var $wrapper = $("#main-wrapper");
  var $togglers = $(".sidebartoggler");
  var desktopBreakpoint = 1200;
  var sidebarStorageKey = "flexytheme.sidebar.collapsed";

  function isDesktop() {
    return window.innerWidth >= desktopBreakpoint;
  }

  function updateToggleState(isExpanded) {
    $togglers.attr("aria-expanded", isExpanded);
  }

  function setSidebarType() {
    if (isDesktop()) {
      var isCollapsed = window.localStorage.getItem(sidebarStorageKey) === "true";
      $wrapper.attr("data-sidebartype", isCollapsed ? "mini-sidebar" : "full").toggleClass("mini-sidebar", isCollapsed).removeClass("show-sidebar");
      updateToggleState(!isCollapsed);
      return;
    }

    $wrapper.attr("data-sidebartype", "mini-sidebar").addClass("mini-sidebar").removeClass("show-sidebar");
    updateToggleState(false);
  }

  setSidebarType();
  $(window).on("resize", setSidebarType);

  $togglers.on("click", function (event) {
    event.preventDefault();

    if (isDesktop()) {
      var isCollapsed = window.localStorage.getItem(sidebarStorageKey) === "true";
      if (isCollapsed) {
        var isExpanded = $wrapper.toggleClass("show-sidebar").hasClass("show-sidebar");
        updateToggleState(isExpanded);
        return;
      }

      $wrapper.attr("data-sidebartype", "mini-sidebar").addClass("mini-sidebar");
      window.localStorage.setItem(sidebarStorageKey, true);
      updateToggleState(false);
      return;
    }

    var isExpanded = $wrapper.toggleClass("show-sidebar").hasClass("show-sidebar");
    updateToggleState(isExpanded);
  });
});
